// RECHAZO EN PUERTA: BLOQUEADO 

const e = $input.first().json;

// Mensaje generico al usuario: nunca se detalla el patron especifico detectado
// (tarjeta, injection, etc.) para no darle pistas de como reformular y evadir
// el filtro en un proximo intento.
const mensajeUsuario = 'Tu mensaje no pudo ser procesado porque contiene informacion sensible o instrucciones no permitidas. Por favor reformula tu solicitud sin incluir datos como numeros de tarjeta, contrasenas, tokens u otras instrucciones dirigidas al asistente.';

// El detalle tecnico SI se conserva para auditoria/log interno,
// nunca se expone en el mensaje que ve el usuario.
const detalleInterno = {
  motivos: e.seguridad?.motivos ?? [],
  patrones_injection: e.seguridad?.injection?.patrones ?? [],
  puntaje_injection: e.seguridad?.injection?.puntaje ?? null,
  umbral_injection: e.seguridad?.injection?.umbral ?? null,
  datos_sensibles: (e.seguridad?.datos_sensibles ?? []).map((h) => h.tipo)
};

return [{ json: {
  status: 'error',
  trace_id: e.trace_id,
  ruta: 'BLOQUEADO_EN_PUERTA',
  accion: 'rechazado',
  mensaje: mensajeUsuario,
  detalle_interno: detalleInterno,
  recibido_en: e.recibido_en ?? null
}}];

// RECHAZO EN PUERTA: INVALIDO 

const e = $input.first().json;

const mensajeUsuario = 'Tu mensaje es demasiado corto o esta incompleto. Por favor incluye el detalle de tu solicitud de horas extra (por ejemplo: fecha, cantidad de horas y el motivo).';

const detalleInterno = {
  motivo: 'longitud de mensaje menor al minimo requerido',
  longitud_recibida: String(e.chatInput ?? '').trim().length,
  longitud_minima: 5
};

return [{ json: {
  status: 'error',
  trace_id: e.trace_id,
  ruta: 'INVALIDO_EN_PUERTA',
  accion: 'rechazado',
  mensaje: mensajeUsuario,
  detalle_interno: detalleInterno,
  recibido_en: e.recibido_en ?? null
}}];

//  WORKER DOS ADAPTER: MENSAJE_INCOMPLETO 

const o = $('Manager de Clasificación').first().json.output ?? {};

return [{ json: {
  status: 'error',
  ruta: 'MENSAJE_INCOMPLETO',
  accion: 'notificado_sin_validar',
  mensaje: 'El mensaje enviado no cumple con lo necesario para evaluar la solicitud: falta la fecha, la cantidad de horas o el motivo/proyecto.',
  clasificacion: {
    ruta: o.ruta ?? 'MENSAJE_INCOMPLETO',
    confianza: o.confianza ?? null,
    motivo_evidencia: o.motivo_evidencia ?? null,
    senales: o.senales ?? []
  }
}}];

//  WORKER DOS ADAPTER: FUERA_DE_CONTEXTO 

const o = $('Manager de Clasificación').first().json.output ?? {};
const senales = o.senales ?? [];
const posibleManipulacion = Array.isArray(senales) &&
  senales.some((s) => /ignor|instruccion|rol|prompt|marc[aá]|clasific/i.test(String(s)));

return [{ json: {
  status: 'error',
  ruta: 'FUERA_DE_CONTEXTO',
  accion: 'notificado_sin_validar',
  mensaje: 'La consulta no corresponde a una solicitud de validacion de horas extra, por lo que no fue procesada por el especialista de politicas.',
  clasificacion: {
    ruta: o.ruta ?? 'FUERA_DE_CONTEXTO',
    confianza: o.confianza ?? null,
    motivo_evidencia: o.motivo_evidencia ?? null,
    senales: senales,
    posible_manipulacion_manager: posibleManipulacion
  }
}}];

// ================= MENSAJE PARA CALL WORKER DOS (post Worker Uno) =================
const o = $('Call Worker Dos').first().json ?? {};
const d = o.data ?? {};

// La "ruta" para el enrutamiento/log viene de la decisión de Worker Uno
// (APROBADO/ESCALADO/FUERA_DE_POLITICA) — el campo "estado" que devuelve
// Worker Dos es un vocabulario distinto (pendiente/aprobado/rechazado/
// en_revision/sin_clasificar), pensado para el registro del caso, no
// para el enrutamiento del sistema.
const ruta = String($('Call Worker Uno').first().json.output?.estado ?? '').toUpperCase();

const ENCABEZADOS = {
  APROBADO: 'Tu solicitud de horas extra fue aprobada.',
  FUERA_DE_POLITICA: 'Tu solicitud de horas extra no cumple con la política vigente.',
  ESCALADO: 'Tu solicitud de horas extra fue escalada para revisión de un supervisor.'
};

const encabezado = ENCABEZADOS[ruta] ?? 'Resultado de tu solicitud de horas extra.';

const mensaje = [
  encabezado,
  '',
  'Fecha: ' + (d.fecha ?? 'no especificada'),
  'Horas extra: ' + (d.horas_extras ?? 'no especificada'),
  'Motivo: ' + (d.motivo ?? 'no especificado'),
  '',
  d.resumen_ejecutivo ?? ''
].join('\n');

return [{ json: {
  trace_id: $('GUARDRAIL DE SEGURIDAD').first().json.trace_id ?? null,
  recibido_en: $('GUARDRAIL DE SEGURIDAD').first().json.recibido_en ?? null,
  status: o.status ?? null,
  ruta: ruta,
  mensaje: mensaje,
  detalle: {
    estado_interno_worker_dos: d.estado ?? null,
    fecha: d.fecha ?? null,
    horas_extras: d.horas_extras ?? null,
    motivo: d.motivo ?? null,
    resumen_ejecutivo: d.resumen_ejecutivo ?? null,
    resolucion: d.resolucion ?? null
  }
}}];

//  MENSAJE DE ERROR 

const o = $('Call Worker Dos').first().json ?? {};

const mensaje = [
  'Lo sentimos, se presentó un error al procesar tu solicitud.',
  'Por favor vuelve a intentarlo. Si el problema persiste, contacta a tu supervisor.'
].join('\n');

return [{ json: {
  status: 'error',
  ruta: 'ERROR_PROCESAMIENTO',
  mensaje: mensaje,
  detalle: {
    error_original: o.error ?? null
  }
}}];

// MENSAJE FALTA_DATO 

const o = $input.first().json.output ?? {};

const datoFaltante = o.dato_faltante ?? 'un dato adicional para completar la validación';

const mensaje = [
  'Tu solicitud no pudo ser resuelta todavía: falta ' + datoFaltante + '.',
  '',
  'Por favor responde con esa información para continuar con la validación.'
].join('\n');

return [{ json: {
  status: 'incompleto',
  ruta: 'FALTA_DATO',
  mensaje: mensaje,
  detalle: {
    tipo_hora_extra: o.tipo_hora_extra ?? null,
    dato_faltante: o.dato_faltante ?? null,
    detalle_tecnico: o.detalle ?? null
  }
}}];

// ================= UNIFICADOR DE RESPUESTA FINAL =================
// Punto de convergencia de TODAS las ramas terminales:
// Bloqueo de Seguridad, Rechazo de Seguridad, Detector MENSAJE_INCOMPLETO,
// Detector FUERA_DE_CONTEXTO, Detector CONSULTA, Detector FALTA DATO,
// Estado_Proceso, Error, Error Worker Uno, Error Worker Dos.
// asi que aca siempre llega un unico item, pero con forma variable
// segun de donde vino. Se normaliza a un contrato unico de salida.

const e = $input.first().json;

let origen = 'DESCONOCIDO';
if (e.ruta === 'BLOQUEADO_EN_PUERTA') origen = 'GUARDRAIL_SEGURIDAD';
else if (e.ruta === 'INVALIDO_EN_PUERTA') origen = 'GUARDRAIL_SEGURIDAD';
else if (e.ruta === 'MENSAJE_INCOMPLETO') origen = 'MANAGER_CLASIFICACION';
else if (e.ruta === 'FUERA_DE_CONTEXTO') origen = 'MANAGER_CLASIFICACION';
else if (e.ruta === 'CONSULTA') origen = 'ENCARGADO_CONSULTAS';
else if (e.ruta === 'FALTA_DATO') origen = 'WORKER_UNO';
else if (e.ruta === 'ERROR_PROCESAMIENTO') origen = e.origen ?? 'WORKER_DESCONOCIDO';
else if (['APROBADO', 'ESCALADO', 'FUERA_DE_POLITICA'].includes(e.ruta)) origen = 'WORKER_DOS';

return [{ json: {
  trace_id: e.trace_id ?? null,
  ruta: e.ruta ?? null,
  origen: origen,
  status: e.status ?? null,
  mensaje: e.mensaje ?? 'No se generó un mensaje para esta ruta.',
  detalle: e.detalle ?? e.detalle_interno ?? e.clasificacion ?? null,
  recibido_en: e.recibido_en ?? null,
  procesado_en: new Date().toISOString()
}}];

// ================= PREPARAR LOG DE OBSERVABILIDAD =================
// Corre para TODA corrida sin importar la rama tomada.
// Relee cada nodo fuente por nombre; algunos no se ejecutan segun
// la rama (ej. Call Worker Uno no existe si el mensaje fue BLOQUEADO),
// por eso el try/catch individual por fuente.

function leer(nombreNodo, extractor, porDefecto = null) {
  try {
    const item = $(nombreNodo).first();
    if (!item) return porDefecto;
    const valor = extractor(item.json);
    return valor === undefined ? porDefecto : valor;
  } catch (e) {
    return porDefecto;
  }
}

const normalizado = $input.first().json;

// --- Siempre disponible: Guardrail de Seguridad corre para todo mensaje ---
const trace_id = leer('GUARDRAIL DE SEGURIDAD', j => j.trace_id, normalizado.trace_id);
const recibido_en = leer('GUARDRAIL DE SEGURIDAD', j => j.recibido_en, normalizado.recibido_en);

// --- Canal y contador de interacciones: siempre disponibles desde el arranque del flujo ---
const canal = leer('Normalizar Contexto de Sesión', j => j.canal, 'desconocido');
const cant_consultas = leer('Normalizar Contexto de Sesión', j => j.Cant_Consultas, null);

// --- Clasificacion del Manager (no corre si fue BLOQUEADO/INVALIDO en el guardrail) ---
const clasificacion = leer('Guardrail de Confianza', j => ({
  ruta: j.clasificacion?.ruta ?? null,
  confianza: j.clasificacion?.confianza ?? null
}));

// --- Parametros enviados a Worker Uno (fecha/horas/motivo, ya redactados si aplico) ---
const params_worker_uno = leer('Edit Fields2', j => ({
  fecha: j.fecha ?? null,
  horas_extras: j.horas_extras ?? null,
  motivo: j.motivo ?? null
}));

// --- Respuesta devuelta por Worker Uno ---
const respuesta_worker_uno = leer('Call Worker Uno', j => ({
  estado: j.output?.estado ?? null,
  detalle: j.output?.detalle ?? null
}));

// --- Parametros enviados a Worker Dos (mismo mapeo que usa el nodo Execute Workflow) ---
const params_worker_dos = leer('Call Worker Uno', j => ({
  output_estado: j.output?.estado ?? null,
  output_detalle: j.output?.detalle ?? null,
  horas_extras: params_worker_uno?.horas_extras ?? null,
  motivo: params_worker_uno?.motivo ?? null,
  fecha: params_worker_uno?.fecha ?? null
}));

// --- Respuesta devuelta por Worker Dos ---
const respuesta_worker_dos = leer('Call Worker Dos', j => ({
  status: j.status ?? null,
  data: j.data ?? null
}));

// --- Parametros enviados a Worker Tres (contexto compartido + consulta, rama CONSULTA) ---
const params_worker_tres = leer('Normalizar Consulta', j => ({
  last_summary: j.last_summary ?? null,
  chatInput: j.chatInput ?? null
}));

// --- Respuesta devuelta por Worker Tres ---
const respuesta_worker_tres = leer('Call Worker Tres', j => ({
  output: j.output_firstItem ?? null
}));

// --- Que workers efectivamente se invocaron en esta corrida ---
let worker_invocado = 'NINGUNO';
if (respuesta_worker_uno && respuesta_worker_dos) worker_invocado = 'WORKER_UNO + WORKER_DOS';
else if (respuesta_worker_uno) worker_invocado = 'WORKER_UNO';
else if (respuesta_worker_tres) worker_invocado = 'WORKER_TRES';

return [{ json: {
  trace_id,
  recibido_en,
  procesado_en: normalizado.procesado_en,
  ruta_final: normalizado.ruta,
  origen: normalizado.origen,
  canal,
  cant_consultas,
  worker_invocado,
  clasificacion_manager: JSON.stringify(clasificacion),
  parametros_worker_uno: JSON.stringify(params_worker_uno),
  respuesta_worker_uno: JSON.stringify(respuesta_worker_uno),
  parametros_worker_dos: JSON.stringify(params_worker_dos),
  respuesta_worker_dos: JSON.stringify(respuesta_worker_dos),
  parametros_worker_tres: JSON.stringify(params_worker_tres),
  respuesta_worker_tres: JSON.stringify(respuesta_worker_tres),
  resultado_usuario: normalizado.mensaje
}}];

// ERROR WORKER DOS

const e = $input.first().json;

return [{ json: {
  status: 'error',
  trace_id: $('GUARDRAIL DE SEGURIDAD').first().json.trace_id ?? null,
  ruta: 'ERROR_PROCESAMIENTO',
  origen: 'WORKER_DOS',
  accion: 'rechazado',
  mensaje: 'Lo sentimos, se presentó un error técnico al enviar el correo de tu solicitud. Por favor vuelve a intentarlo. Si el problema persiste, contacta a tu supervisor.',
  detalle: {
    error_original: e.error?.message ?? String(e.error ?? 'error desconocido')
  }
}}];

// ERROR WORKER UNO

const e = $input.first().json;

return [{ json: {
  status: 'error',
  trace_id: $('GUARDRAIL DE SEGURIDAD').first().json.trace_id ?? null,
  ruta: 'ERROR_PROCESAMIENTO',
  origen: 'WORKER_UNO',
  accion: 'rechazado',
  mensaje: 'Lo sentimos, se presentó un error técnico al validar tu solicitud de horas extra. Por favor vuelve a intentarlo. Si el problema persiste, contacta a tu supervisor.',
  detalle: {
    error_original: e.error?.message ?? String(e.error ?? 'error desconocido')
  }
}}];

// Normalizar Contexto de Sesión
// Punto de merge entre "Usuario Existente" y "Usuario Nuevo (Sin Contexto)".
// Garantiza que los campos de contexto siempre existan con un tipo
// consistente, sin importar de qué rama vino el item, y queda como
// punto de referencia fijo para cualquier nodo posterior del flujo.

const item = $input.first().json;

const chatInput = item.chatInput ?? '';
const sessionId = item.sessionId ?? '';
const canal = typeof item.canal === 'string' && item.canal !== '' ? item.canal : 'desconocido';

const last_summary = typeof item.last_summary === 'string' ? item.last_summary : '';
const airtable_record_id = item.airtable_record_id ?? null;

const estado_anterior = (typeof item.estado_anterior === 'string' && item.estado_anterior !== '')
  ? item.estado_anterior
  : 'recibido';
const datos_clave_anterior = typeof item.datos_clave_anterior === 'string' ? item.datos_clave_anterior : '';

const contador_previo = Number.isFinite(Number(item.Cant_Consultas)) ? Number(item.Cant_Consultas) : 0;
const Cant_Consultas = contador_previo + 1;

// Email del solicitante (solo presente cuando el canal es 'gmail'; null en otros canales).
const email_solicitante = typeof item.email_solicitante === 'string' && item.email_solicitante !== ''
  ? item.email_solicitante
  : null;

return [{ json: {
  chatInput,
  sessionId,
  canal,
  last_summary,
  airtable_record_id,
  estado_anterior,
  datos_clave_anterior,
  Cant_Consultas,
  email_solicitante
}}];

// Guardrail semantico

const UMBRAL_CONFIANZA = 0.5;
const RUTAS_VALIDAS = ['PROCESABLE', 'CONSULTA', 'MENSAJE_INCOMPLETO', 'FUERA_DE_CONTEXTO'];

const entrada = $('GUARDRAIL DE SEGURIDAD').first().json;
const salida = [];

for (const item of $input.all()) {
  const c = item.json.output ?? item.json;

  const rutaModelo = String(c.ruta ?? '').toUpperCase();
  const confianza = Number(c.confianza ?? 0);

  let ruta = rutaModelo;
  let motivo_guardrail = null;

  if (!RUTAS_VALIDAS.includes(rutaModelo)) {
    ruta = 'MENSAJE_INCOMPLETO';
    motivo_guardrail = 'el modelo devolvio una ruta fuera de la taxonomia: "' + rutaModelo + '"';
  } else if (!Number.isFinite(confianza) || confianza < UMBRAL_CONFIANZA) {
    ruta = 'MENSAJE_INCOMPLETO';
    motivo_guardrail = 'confianza ' + confianza + ' por debajo del umbral ' + UMBRAL_CONFIANZA;
  }

  salida.push({ json: {
    trace_id: entrada.trace_id,
    chatInput: entrada.chatInput,
    sessionId: entrada.sessionId,
    seguridad: entrada.seguridad,
    clasificacion: {
      ruta: rutaModelo,
      confianza: confianza,
      motivo_evidencia: c.motivo_evidencia ?? null,
      senales: c.senales ?? []
    },
    ruta: ruta,
    guardrail_aplicado: motivo_guardrail !== null,
    motivo_guardrail: motivo_guardrail,
    fecha: c.fecha ?? null,
    horas_extras: c.horas_extras ?? null,
    motivo: c.motivo ?? null,
    email_solicitante: entrada.email_solicitante ?? null
  }});
}

return salida;

