// Parsear Resumen JSON
// Convierte el texto plano devuelto por "Basic LLM Chain" (que debería
// ser un JSON válido según su prompt) en un objeto real, validado contra
// el contrato exacto {asunto_principal, puntos_clave[], accion_requerida}.

const raw = String($input.first().json.text ?? '').trim();

// Por si el modelo ignora la instrucción de "sin backticks" y los agrega igual
const limpio = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();

const ENUM_VALIDO = ['recibido', 'en proceso', 'escalado', 'resuelto'];

let parsed;
try {
  parsed = JSON.parse(limpio);
} catch (e) {
  // Fallback defensivo: si el LLM no devolvió JSON válido, no rompemos
  // la ejecución — marcamos el caso como "escalado" (requiere revisión
  // humana) en vez de perder el registro o tirar un error no controlado.
  return [{ json: {
    asunto_principal: 'ERROR DE PARSEO: ' + raw.slice(0, 200),
    puntos_clave: [],
    accion_requerida: 'escalado'
  }}];
}

const accion = ENUM_VALIDO.includes(parsed.accion_requerida) ? parsed.accion_requerida : 'escalado';
const puntos = Array.isArray(parsed.puntos_clave) ? parsed.puntos_clave.filter((p) => typeof p === 'string') : [];

return [{ json: {
  asunto_principal: typeof parsed.asunto_principal === 'string' ? parsed.asunto_principal : '',
  puntos_clave: puntos,
  accion_requerida: accion
}}];

// Preparar Payload (Con Resumen)
// Mapea el contrato {asunto_principal, puntos_clave[], accion_requerida}
// a las columnas fijas de Memoria_Clientes, y fija Session_ID /
// Fecha_Actualizacion / Cant_Consultas acá (nunca dejar que el
// LLM genere estos tres campos).

const resumen = $input.first().json;
const ctx = $('Normalizar Contexto de Sesión').first().json;


return [{ json: {
  Session_ID: ctx.sessionId,
  Fecha_Actualizacion: $now.toUTC().toISO({ suppressMilliseconds: true }),
  Resumen_Consolidado: resumen.asunto_principal,
  Estado_del_Caso: resumen.accion_requerida,
  Datos_Clave: resumen.puntos_clave.join('; '),
  Cant_Consultas: 0
}}];

// Preparar Payload (Sin Resumen)
// La conversación todavía no supera los 5 intercambios: no se gasta una
// llamada a LLM de resumen. Solo se deja constancia del turno (contador
// y timestamp) y se re-escriben los valores existentes tal cual, para
// no perder lo que ya estaba consolidado.
//
// Se usa .first() en vez de .item porque esta referencia cruza el nodo
// AI Agent (Encargado Consultas); el emparejamiento implícito de .item
// puede colgarse cuando el pairedItem no se propaga bien a través de
// nodos LangChain (Agent/Tool/Memory).

const ctx = $('Normalizar Contexto de Sesión').first().json;

return [{ json: {
  Session_ID: ctx.sessionId,
  Fecha_Actualizacion: $now.toUTC().toISO({ suppressMilliseconds: true }),
  Resumen_Consolidado: ctx.last_summary,
  Estado_del_Caso: ctx.estado_anterior,
  Datos_Clave: ctx.datos_clave_anterior,
  Contador_Interacciones: ctx.contador_interacciones
}}];

//  WORKER ADAPTER: CONSULTA

const respuestaAgente = String($('Call Worker Tres').first().json.output_firstItem ?? '').trim();
const o = $('Manager de Clasificación').first().json.output ?? {};
const senales = o.senales ?? [];
const posibleManipulacion = Array.isArray(senales) &&
  senales.some((s) => /ignor|instruccion|rol|prompt|marc[aá]|clasific/i.test(String(s)));

const respuestaValida = respuestaAgente.length > 0;

return [{ json: {
  status: respuestaValida ? 'ok' : 'error',
  ruta: 'CONSULTA',
  accion: respuestaValida ? 'consulta_respondida' : 'consulta_sin_respuesta_agente',
  mensaje: respuestaValida
    ? respuestaAgente
    : 'El agente de consultas no genero una respuesta valida para este mensaje.',
  clasificacion: {
    ruta: o.ruta ?? 'CONSULTA',
    confianza: o.confianza ?? null,
    motivo_evidencia: o.motivo_evidencia ?? null,
    senales: senales,
    posible_manipulacion_manager: posibleManipulacion
  }
}}];

// Detectar Canal
// Identifica desde qué trigger llegó el mensaje y normaliza el payload
// a una forma única {chatInput, sessionId, canal} para el resto del flujo.
//
// Al agregar un nuevo canal (Gmail, WhatsApp, etc.):
// 1. Agrega ese trigger al array CANALES de abajo, con su propio extractor.
// 2. Conecta el nuevo trigger a este mismo nodo (main output -> este nodo).
// No hace falta tocar ningún otro nodo del flujo: todo lo demás lee
// chatInput / sessionId / canal de forma genérica desde aquí en adelante.

const CANALES = [
  {
    nodo: 'Chat Trigger',
    canal: 'chat',
    extraer: (j) => ({ chatInput: j.chatInput, sessionId: j.sessionId })
  },
  {
    nodo: 'Gmail Trigger',
    canal: 'gmail',
    extraer: (j) => ({ chatInput: j.snippet, sessionId: j.threadId, email: j.From })
  },  
];

let resultado = null;

for (const c of CANALES) {
  try {
    const item = $(c.nodo).first();
    if (item) {
      const datos = c.extraer(item.json);
      resultado = { chatInput: datos.chatInput ?? '', sessionId: datos.sessionId ?? '', canal: c.canal };
      break;
    }
  } catch (e) {
    // Este trigger no existe o no corrió en esta ejecución: se prueba el siguiente.
  }
}

if (!resultado) {
  resultado = { chatInput: '', sessionId: '', canal: 'desconocido' };
}

return [{ json: resultado }];
